// Consolida os dados coletados: monta indicadores + prompt (resposta em JSON)
const fmtBR = (n, dec) => Number(n).toLocaleString('pt-BR', { minimumFractionDigits: dec, maximumFractionDigits: dec });
const indicadores = [];
const macro = [];
const paraTexto = [];

// Ibovespa
try {
  const ibov = $('Ibovespa (brapi)').first().json.results[0];
  const d = ibov.regularMarketChangePercent ?? null;
  indicadores.push({ nome: 'Ibovespa', valor: fmtBR(ibov.regularMarketPrice, 0) + ' pts', delta: d });
  paraTexto.push('Ibovespa: ' + fmtBR(ibov.regularMarketPrice, 0) + ' pts (' + (d ?? 0).toFixed(2) + '% no dia)');
} catch (e) {}

// Câmbio
try {
  const fx = $('Câmbio (AwesomeAPI)').first().json;
  indicadores.push({ nome: 'Dólar', valor: 'R$ ' + fmtBR(fx.USDBRL.bid, 2), delta: Number(fx.USDBRL.pctChange) });
  indicadores.push({ nome: 'Euro', valor: 'R$ ' + fmtBR(fx.EURBRL.bid, 2), delta: Number(fx.EURBRL.pctChange) });
  paraTexto.push('Dólar: R$ ' + fmtBR(fx.USDBRL.bid, 2) + ' (' + fx.USDBRL.pctChange + '%)');
  paraTexto.push('Euro: R$ ' + fmtBR(fx.EURBRL.bid, 2) + ' (' + fx.EURBRL.pctChange + '%)');
} catch (e) {}

// Yahoo
const yah = (nome, node, prefixo) => {
  try {
    const m = $(node).first().json.chart.result[0].meta;
    const ant = m.chartPreviousClose ?? m.previousClose;
    const d = ant ? ((m.regularMarketPrice - ant) / ant) * 100 : null;
    indicadores.push({ nome: nome, valor: prefixo + fmtBR(m.regularMarketPrice, 2), delta: d });
    paraTexto.push(nome + ': ' + fmtBR(m.regularMarketPrice, 2) + ' (' + (d ?? 0).toFixed(2) + '%)');
  } catch (e) {}
};
yah('S&P 500', 'S&P 500 (Yahoo)', '');
yah('Nasdaq', 'Nasdaq (Yahoo)', '');
yah('Petróleo WTI', 'Petróleo WTI (Yahoo)', 'US$ ');
yah('Ouro', 'Ouro (Yahoo)', 'US$ ');

// Macro Brasil
try {
  const s = $('Selic (BCB)').first().json[0].valor;
  macro.push({ nome: 'Selic (meta)', valor: String(s).replace('.', ',') + '% a.a.' });
  paraTexto.push('Selic: ' + s + '% a.a.');
} catch (e) {}
try {
  const i = $('IPCA (BCB)').first().json[0].valor;
  macro.push({ nome: 'IPCA (mês)', valor: String(i).replace('.', ',') + '%' });
  paraTexto.push('IPCA último mês: ' + i + '%');
} catch (e) {}

// Notícias
let noticiasBR = '', noticiasGlobal = '';
try { noticiasBR = $('Notícias BR (InfoMoney)').all().slice(0, 8).map(i => '- ' + i.json.title).join('\n'); } catch (e) {}
try { noticiasGlobal = $('Notícias Global (CNBC)').all().slice(0, 8).map(i => '- ' + i.json.title).join('\n'); } catch (e) {}

const agora = new Date();
const dataFmt = agora.toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo', weekday: 'long', day: '2-digit', month: 'long', year: 'numeric' });
const horaFmt = agora.toLocaleTimeString('pt-BR', { timeZone: 'America/Sao_Paulo', hour: '2-digit', minute: '2-digit' });

const prompt = 'Você é o estrategista-chefe de um fundo de investimentos escrevendo o briefing matinal de ' + dataFmt + ' para o gestor. Tom sóbrio, direto, analítico — padrão de banco de investimento. Sem exclamações, sem clichês.\n\n' +
  'DADOS DE MERCADO:\n' + paraTexto.join('\n') + '\n\n' +
  'MANCHETES BRASIL (InfoMoney):\n' + (noticiasBR || 'indisponível') + '\n\n' +
  'MANCHETES GLOBAIS (CNBC):\n' + (noticiasGlobal || 'indisponível') + '\n\n' +
  'Responda SOMENTE com um JSON válido, sem markdown, neste formato exato:\n' +
  '{\n' +
  '  "manchete": "uma frase-título do dia, máx 90 caracteres, conectando o principal movimento",\n' +
  '  "visao_geral": "2-3 frases conectando o cenário global e local do dia",\n' +
  '  "brasil": "3-4 frases sobre Ibovespa, câmbio e o que explica os movimentos, citando Selic/IPCA se relevante",\n' +
  '  "eua_mundo": "3-4 frases sobre índices americanos, commodities e contexto macro global",\n' +
  '  "noticias": [ { "titulo": "manchete 1", "contexto": "1 frase de por que importa" }, { "titulo": "manchete 2", "contexto": "..." }, { "titulo": "manchete 3", "contexto": "..." } ]\n' +
  '}\n' +
  'Use apenas texto puro nos valores (sem HTML, sem aspas duplas internas). Se algum dado estiver indisponível, simplesmente não o mencione.';

return [{ json: { prompt, indicadores, macro, dataFmt, horaFmt } }];

function montarEmail(base, ia) {
  const rowsSnapshot = (base.indicadores || []).map(function (i) {
    let chip = '<span style="font-family:\'Courier New\',monospace;font-size:12px;color:#8B9EC7;">&mdash;</span>';
    if (i.delta !== null && i.delta !== undefined && isFinite(i.delta)) {
      const up = i.delta >= 0;
      const bg = up ? 'rgba(34,197,94,0.15)' : 'rgba(239,68,68,0.15)';
      const fg = up ? '#4ADE80' : '#F87171';
      const seta = up ? '&#9650;' : '&#9660;';
      const val = (up ? '+' : '') + i.delta.toFixed(2).replace('.', ',') + '%';
      chip = '<span style="display:inline-block;padding:3px 10px;border-radius:999px;background:' + bg + ';color:' + fg + ';font-family:\'Courier New\',monospace;font-size:12px;font-weight:700;white-space:nowrap;">' + seta + ' ' + val + '</span>';
    }
    return '<tr>' +
      '<td style="padding:8px 0;font-family:Arial,Helvetica,sans-serif;font-size:11px;letter-spacing:1.2px;color:#8B9EC7;text-transform:uppercase;font-weight:700;">' + i.nome + '</td>' +
      '<td align="right" style="padding:8px 0;font-family:\'Courier New\',monospace;font-size:14px;color:#FFFFFF;font-weight:700;white-space:nowrap;">' + i.valor + '</td>' +
      '<td align="right" width="96" style="padding:8px 0 8px 14px;">' + chip + '</td>' +
      '</tr>';
  }).join('');

  function secao(kicker, texto) {
    if (!texto) return '';
    return '<tr><td style="padding:26px 36px 0;">' +
      '<div style="font-family:Arial,Helvetica,sans-serif;font-size:11px;letter-spacing:1.6px;color:#0099CC;text-transform:uppercase;font-weight:800;padding-bottom:10px;border-bottom:2px solid #E8ECF5;margin-bottom:14px;">' + kicker + '</div>' +
      '<p style="margin:0;font-family:Georgia,\'Times New Roman\',serif;font-size:15px;line-height:1.65;color:#33415C;">' + texto + '</p>' +
      '</td></tr>';
  }

  const noticias = (ia.noticias || []).slice(0, 3).map(function (n, idx) {
    return '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin-top:' + (idx === 0 ? '0' : '18px') + ';"><tr>' +
      '<td width="44" valign="top" style="font-family:\'Courier New\',monospace;font-size:22px;font-weight:700;color:#00BFFF;">0' + (idx + 1) + '</td>' +
      '<td valign="top">' +
      '<div style="font-family:Arial,Helvetica,sans-serif;font-size:14px;font-weight:700;color:#1A2442;line-height:1.4;">' + (n.titulo || '') + '</div>' +
      '<div style="font-family:Georgia,serif;font-size:13px;color:#5A6880;line-height:1.55;margin-top:4px;">' + (n.contexto || '') + '</div>' +
      '</td></tr></table>';
  }).join('');

  const blocoNoticias = noticias
    ? '<tr><td style="padding:26px 36px 0;">' +
      '<div style="font-family:Arial,Helvetica,sans-serif;font-size:11px;letter-spacing:1.6px;color:#0099CC;text-transform:uppercase;font-weight:800;padding-bottom:10px;border-bottom:2px solid #E8ECF5;margin-bottom:16px;">Tr&ecirc;s hist&oacute;rias para acompanhar</div>' +
      noticias + '</td></tr>'
    : '';

  const macro = (base.macro || []).map(function (m) {
    return '<td align="center" style="padding:12px 8px;background:#F0F4FF;border-radius:10px;">' +
      '<div style="font-family:Arial,Helvetica,sans-serif;font-size:10px;letter-spacing:1.2px;color:#8B9EC7;text-transform:uppercase;font-weight:700;">' + m.nome + '</div>' +
      '<div style="font-family:\'Courier New\',monospace;font-size:16px;font-weight:700;color:#1A2442;margin-top:4px;">' + m.valor + '</div>' +
      '</td>';
  }).join('<td width="10"></td>');

  const blocoMacro = macro
    ? '<tr><td style="padding:26px 36px 0;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr>' + macro + '</tr></table></td></tr>'
    : '';

  return '<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head>' +
    '<body style="margin:0;padding:0;background:#F0F4FF;">' +
    '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#F0F4FF;"><tr><td align="center" style="padding:28px 12px;">' +
    '<table role="presentation" width="600" cellpadding="0" cellspacing="0" style="max-width:600px;width:100%;">' +

    // ===== MASTHEAD =====
    '<tr><td style="background:#040F2B;border-radius:14px 14px 0 0;padding:30px 36px 26px;">' +
    '<table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr>' +
    '<td style="font-family:Arial,Helvetica,sans-serif;font-size:17px;font-weight:800;letter-spacing:-0.3px;color:#FFFFFF;">INTELIG&Ecirc;NCIA DE MERCADO<span style="color:#00BFFF;">.</span></td>' +
    '<td align="right" style="font-family:Arial,Helvetica,sans-serif;font-size:10px;letter-spacing:1.4px;color:#8B9EC7;text-transform:uppercase;font-weight:700;">Briefing di&aacute;rio</td>' +
    '</tr></table>' +
    '<div style="font-family:Arial,Helvetica,sans-serif;font-size:11px;letter-spacing:1.2px;color:#8B9EC7;text-transform:uppercase;margin-top:18px;">' + (base.dataFmt || '') + '</div>' +
    '<div style="font-family:Georgia,\'Times New Roman\',serif;font-size:24px;line-height:1.3;color:#FFFFFF;margin-top:8px;font-weight:700;">' + (ia.manchete || 'Resumo do mercado') + '</div>' +
    '</td></tr>' +

    // ===== SNAPSHOT (banda escura) =====
    '<tr><td style="background:#0A1E4A;padding:20px 36px 22px;">' +
    '<div style="font-family:Arial,Helvetica,sans-serif;font-size:10px;letter-spacing:1.6px;color:#00BFFF;text-transform:uppercase;font-weight:800;margin-bottom:8px;">Mercados agora</div>' +
    '<table role="presentation" width="100%" cellpadding="0" cellspacing="0">' + rowsSnapshot + '</table>' +
    '</td></tr>' +

    // ===== CORPO =====
    '<tr><td style="background:#FFFFFF;padding:2px 0 0;">' +
    '<table role="presentation" width="100%" cellpadding="0" cellspacing="0">' +
    secao('Vis&atilde;o geral', ia.visao_geral) +
    blocoMacro +
    secao('Brasil', ia.brasil) +
    secao('EUA e mundo', ia.eua_mundo) +
    blocoNoticias +
    '<tr><td style="padding:30px 36px;"></td></tr>' +
    '</table></td></tr>' +

    // ===== RODAPÉ =====
    '<tr><td style="background:#040F2B;border-radius:0 0 14px 14px;padding:20px 36px;">' +
    '<div style="font-family:Arial,Helvetica,sans-serif;font-size:11px;color:#8B9EC7;line-height:1.6;">Gerado automaticamente &agrave;s ' + (base.horaFmt || '') + ' &middot; Fontes: B3 (brapi), Banco Central do Brasil, Yahoo Finance, InfoMoney, CNBC</div>' +
    '<div style="font-family:Arial,Helvetica,sans-serif;font-size:10px;color:#5A6880;line-height:1.6;margin-top:8px;">Material de car&aacute;ter exclusivamente informativo. N&atilde;o constitui oferta, recomenda&ccedil;&atilde;o ou aconselhamento de investimento. Rentabilidade passada n&atilde;o garante resultados futuros.</div>' +
    '</td></tr>' +

    '</table></td></tr></table></body></html>';
}


const resp = $('Gemini — Análise do dia').first().json;
let ia = {};
try {
  ia = JSON.parse(resp.candidates[0].content.parts[0].text);
} catch (e) {
  const bruto = (((resp.candidates || [])[0] || {}).content || {}).parts;
  ia = { manchete: 'Resumo do mercado', visao_geral: bruto && bruto[0] ? bruto[0].text : 'Análise indisponível hoje.', brasil: '', eua_mundo: '', noticias: [] };
}
const base = $('Consolidar dados').first().json;
return [{ json: { html: montarEmail(base, ia) } }];
